using System;
using System.Linq;
using Deception.Core;
using Deception.PolyModAdapter;
namespace Deception.Tests
{
 public static partial class RogueTests
 {
  static PlayerState Player(GameState s,byte id=1){s.TryGetPlayer(id,out var p);return p!;}
  static LedgerUnit Row(GameState s,uint id)=>Read(s).Units.Single(r=>r.NativeId==id);
  static void InvestmentCases()
  {
   Test("investment-registers-only-native-purchase-and-refund-boundaries",()=>{var h=new HarmonyLib.Harmony();NativeInvestment.Install(h);Check(h.Hooks.SequenceEqual(new[]{"TrainAction.Execute","UpgradeAction.Execute","DisbandUnitAction.Execute","UnitState.GetFullCost"}),"no apparent upgrade or UI cost accounting");});
   Test("investment-known-birth-records-exact-native-debit",()=>{var s=Make();var a=new TrainAction{PlayerId=1,Coordinates=new(3,3),Type=UnitType.warrior,Cost=2};NativeInvestment.BeforeTrain(a,s,out var scope);Player(s).Currency-=2;Tile(s,3,3).unit=new(){id=4,owner=1,coordinates=new(3,3)};NativeInvestment.AfterPurchase(scope,true);var r=Row(s,4);Check(r.InvestmentKind==PaidInvestmentKind.Known&&r.PaidStars==2,"new physical unit records actual paid stars");Check(Row(s,1).PaidStars==3&&Row(s,2).PaidStars==3,"unrelated investments retained");});
   Test("investment-known-upgrade-accumulates-actual-price",()=>{var s=Make();var a=new UpgradeAction{PlayerId=1,Coordinates=new(0,0),Cost=5};NativeInvestment.BeforeUpgrade(a,s,out var scope);Player(s).Currency-=5;NativeInvestment.AfterPurchase(scope,true);Check(Row(s,1).PaidStars==8&&Row(s,1).InvestmentKind==PaidInvestmentKind.Known,"genuine upgrade adds to genuine training investment");});
   Test("investment-unknown-legacy-upgrade-stays-unknown",()=>{var s=Make();Write(s,Read(s) with{Units=Read(s).Units.Select(r=>r.NativeId==1?r with{InvestmentKind=PaidInvestmentKind.UnknownLegacy,PaidStars=0}:r).ToArray()});NativeInvestment.BeforeUpgrade(new UpgradeAction{PlayerId=1,Coordinates=new(0,0),Cost=5},s,out var scope);Player(s).Currency-=5;NativeInvestment.AfterPurchase(scope,true);Check(Row(s,1).InvestmentKind==PaidInvestmentKind.UnknownLegacy&&Row(s,1).PaidStars==0,"one observed upgrade does not invent unrecorded training investment");});
   Test("investment-free-upgrade-cannot-increase-refund",()=>{var s=Make();NativeInvestment.BeforeUpgrade(new UpgradeAction{PlayerId=1,Coordinates=new(0,0),Cost=0},s,out var scope);NativeInvestment.AfterPurchase(scope,true);Check(Row(s,1).PaidStars==3&&Player(s).Currency==37,"zero debit preserves paid amount and bank");});
   foreach(string failure in new[]{"skipped","wrong-debit","no-unit","negative-cost"})Test("investment-no-credit-on-"+failure,()=>{var s=Make();var a=new TrainAction{PlayerId=1,Coordinates=new(3,3),Type=UnitType.warrior,Cost=failure=="negative-cost"?-1:2};NativeInvestment.BeforeTrain(a,s,out var scope);Player(s).Currency-=failure=="wrong-debit"?1:2;if(failure!="no-unit")Tile(s,3,3).unit=new(){id=4,owner=1,coordinates=new(3,3)};NativeInvestment.AfterPurchase(scope,failure!="skipped");Check(!Read(s).Units.Any(r=>r.NativeId==4),"unverified native purchase creates no invented investment");});
   Test("investment-mimic-training-retains-existing-native-carrier-ledger",()=>{var s=Make();NativeInvestment.BeforeTrain(new TrainAction{PlayerId=1,Coordinates=new(3,3),Type=UnitType.dcp_mimic_form_warrior,Cost=RecruitmentCatalog.Cost},s,out var scope);Check(scope is null,"dedicated Mimic purchase path not double-accounted");});
   Test("investment-rogue-paid-upgrade-uses-commanders-bank",()=>{var s=Make();NativeInvestment.BeforeUpgrade(new UpgradeAction{PlayerId=1,Coordinates=new(1,2),Cost=5},s,out var scope);Player(s).Currency-=5;NativeInvestment.AfterPurchase(scope,true);Check(Row(s,2).PaidStars==8&&Player(s,2).Currency==37,"temporary command pays, remembered owner bank unaffected");NativeRogueRules.AfterStart(new StartTurnAction{PlayerId=2},s);Check(Row(s,2).PaidStars==8&&Unit(s,2).owner==2,"improved genuine investment returns with physical body");});
   Test("investment-upgrade-refuses-replaced-root-identity",()=>{var s=Make();NativeInvestment.BeforeUpgrade(new UpgradeAction{PlayerId=1,Coordinates=new(0,0),Cost=5},s,out var scope);Player(s).Currency-=5;Tile(s,0,0).unit=new(){id=9,owner=1};bool refused=false;try{NativeInvestment.AfterPurchase(scope,true);}catch(System.IO.InvalidDataException){refused=true;}Check(refused&&Row(s,1).PaidStars==3,"unexpected native physical replacement cannot inherit investment silently");});
   Test("investment-vessel-keeps-passenger-identity-separate",()=>{var s=Make();var u=Unit(s,1);u.passengerUnit=new(){id=9,owner=1};u.type=UnitType.transportship;Write(s,Read(s) with{Units=Read(s).Units.Select(r=>r.NativeId==1?r with{Transport=new(9)}:r).ToArray()});NativeInvestment.BeforeUpgrade(new UpgradeAction{PlayerId=1,Coordinates=new(0,0),Cost=5},s,out var scope);Player(s).Currency-=5;NativeInvestment.AfterPurchase(scope,true);Check(Row(s,1).Transport!.PassengerNativeId==9&&Row(s,1).PaidStars==8&&u.passengerUnit.id==9,"upgrade investment belongs to transport identity without replacing cargo");});
   Test("investment-refund-scopes-exact-native-cost",()=>{var s=Make();var u=Unit(s,1);var old=new IncreaseCurrencyAction{PlayerId=1,Source=new(0,0),Amount=12};s.ActionStack.Add(old);var action=new DisbandUnitAction{PlayerId=1,Coordinates=u.coordinates,GetPaid=true};s.ActionStack.Add(action);NativeInvestment.BeforeDisband(action,s,out var scope);Check(u.GetFullCost(s)==3&&Unit(s,2).GetFullCost(s)==20,"only exact body uses its genuine paid cost before native division");NativeInvestment.DisbandFinished(null,scope);Check(u.GetFullCost(s)==20&&old.Amount==12,"cost scope or prior queued reward was changed outside native action");});
   foreach(string context in new[]{"rogue","unknown","skipped"})Test("investment-refund-no-custom-authority-"+context,()=>{var s=Make();uint id=context=="rogue"?2u:1u;if(context=="unknown")Write(s,Read(s) with{Units=Read(s).Units.Select(r=>r.NativeId==1?r with{InvestmentKind=PaidInvestmentKind.UnknownLegacy,PaidStars=0}:r).ToArray()});var u=Unit(s,id);var action=new DisbandUnitAction{PlayerId=1,Coordinates=u.coordinates,GetPaid=true};if(context!="skipped")s.ActionStack.Add(action);NativeInvestment.BeforeDisband(action,s,out var scope);Check(u.GetFullCost(s)==20,"Rogue, unknown investment or unqueued action acquired genuine cost override");NativeInvestment.DisbandFinished(null,scope);});

  }
 }
}
